package com.hms.website;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="custom_domains") public class CustomDomain { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false,unique=true,length=253) private String domain; @Column(nullable=false,length=120) private String verificationToken; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private CustomDomainStatus status; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private SslStatus sslStatus; private OffsetDateTime verifiedAt; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected CustomDomain(){} public CustomDomain(UUID tenantId,String domain){this.id=UUID.randomUUID();this.tenantId=tenantId;this.domain=domain.trim().toLowerCase();this.verificationToken="hms-verify-"+UUID.randomUUID();this.status=CustomDomainStatus.PENDING_VERIFICATION;this.sslStatus=SslStatus.PENDING;this.createdAt=OffsetDateTime.now();this.updatedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getDomain(){return domain;} public String getVerificationToken(){return verificationToken;} public CustomDomainStatus getStatus(){return status;} public SslStatus getSslStatus(){return sslStatus;} public OffsetDateTime getVerifiedAt(){return verifiedAt;} public void verify(String observed){if(!verificationToken.equals(observed))throw new IllegalArgumentException("Domain verification token does not match");status=CustomDomainStatus.VERIFIED;sslStatus=SslStatus.ACTIVE;verifiedAt=OffsetDateTime.now();updatedAt=verifiedAt;} public void disable(){status=CustomDomainStatus.DISABLED;sslStatus=SslStatus.PENDING;updatedAt=OffsetDateTime.now();} }
